+                        if(taskCounters != null) {
+                            if(counters == null) {
+                              counters = taskCounters;
+                            } else {
+                              counters.incrAllCounters(taskCounters);
+                            }
                         } else {
-                          counters.incrAllCounters(taskCounters);
+                          XLog.getLog(getClass()).warn("Could not find Hadoop Counters for job: [{0}]", jobId);
                         }
-                    } else {
-                      XLog.getLog(getClass()).warn("Could not find Hadoop Counters for job: [{0}]", jobId);
                     }
                 }


